"""Python exercises. `tests` run in the sandbox after the learner's code, sharing its namespace.
Every `solution` is executed against its own tests by the backend test-suite."""
from __future__ import annotations


def ex(id, title, category, level, prompt, hints, starter, expected, solution, tests, explain="", topic="python"):
    return {"id": id, "title": title, "category": category, "level": level, "prompt": prompt, "hints": hints,
            "starter": starter.strip("\n") + "\n", "expected": expected, "solution": solution.strip("\n") + "\n",
            "tests": tests.strip("\n") + "\n", "solution_explain": explain, "topic": topic}


B, I, A = "beginner", "intermediate", "advanced"

